import math

def is_power_of_two(v):
    """Checks if a positive integer v is a power of 2."""
    if v <= 0:
        return False
    return (v & (v - 1)) == 0

def solve_search():
    solutions = []

    # Iterate over n from 2 to 5
    for n in range(2, 6):
        # Iterate over x from n+1 to 15
        for x in range(n + 1, 16):
            # Calculate V = x^n + x - 2
            try:
                V = x**n + x - 2
            except OverflowError:
                # Should not happen with these small bounds, but good practice
                continue

            if V > 0 and is_power_of_two(V):
                # V is a power of 2, so k = log2(V)
                k = int(math.log2(V))

                # Check if k is a positive integer (since V >= 1, k >= 0. 
                # Since V = x^n + x - 2, and x>=3, n>=2, V >= 3^2+3-2 = 10, so k >= 4)
                if k >= 1:
                    solutions.append((x, n, k))

    return solutions

results = solve_search()
print(results)

def solve():
    solutions = []
    for n in range(2, 10):
        for x in range(n + 1, 100):
            val = x**n + x - 2
            if val > 0 and (val & (val - 1) == 0):
                k = val.bit_length() - 1
                solutions.append((x, n, k))
    return solutions

print(solve())

